class H(HTMLParser):
    def __init__(s):
        super().__init__();s.meta=[];s.links=[];s.a=[];s.h=[];s.img=[];s.text=[];s.skip=0;s.cur=None;s.title='';s.intitle=False;s.ld=0;s.scripts=0;s.lang=None;s.buf=''
    def handle_starttag(s,t,a):
        a=dict(a)
        if t=='html':s.lang=a.get('lang')
        if t=='meta':s.meta.append(a)
        if t=='link':s.links.append(a)
        if t=='a':s.a.append(a.get('href'))
        if t=='img':s.img.append(a)
        if t in('script','style'):
            s.skip+=1
            if t=='script':
                s.scripts+=1
